var e={id:0,title:{ar:"\u0627\u0644\u0641\u0635\u0644 0",en:"Chapter 0"},name:{ar:"\u0627\u0644\u0648\u0635\u0648\u0644",en:"Arrival"},narrator:{ar:"\u0627\u0644\u0631\u0627\u0648\u064A",en:"Narrator"},intro:[{ar:"\u0648\u0635\u0644\u062A\u064E \u0627\u0644\u0644\u064A\u0644\u0629 \u0628\u0627\u0644\u0642\u0637\u0627\u0631 \u0627\u0644\u0645\u063A\u0646\u0627\u0637\u064A\u0633\u064A\u060C {name}. \u0647\u0630\u0647 \u0634\u0642\u062A\u0643 \u0627\u0644\u062C\u062F\u064A\u062F\u0629 \u0641\u064A \u0627\u0644\u0645\u062F\u064A\u0646\u0629 \u0627\u0644\u0631\u0642\u0645\u064A\u0629.",en:"You came in on the magnetic train tonight, {name}. This is your new apartment in the Digital City."},{ar:"\u0641\u064A \u062C\u064A\u0628\u0643 \u0645\u0641\u062A\u0627\u062D \u0623\u0628\u064A\u0643 \u0627\u0644\u0646\u062D\u0627\u0633\u064A\u060C \u0631\u0642\u0645 40\u2026 \u0648\u0641\u064A \u0631\u0623\u0633\u0643 \u0635\u0648\u062A\u0647: \xAB\u0644\u0627 \u062A\u062B\u0642 \u0628\u0627\u0644\u0634\u0627\u0634\u0627\u062A\xBB.",en:"Your father's brass key, number 40, is in your pocket\u2026 and his voice is in your head: \u201CDon't trust the screens.\u201D"},{ar:"\u0647\u0646\u0627 \u0644\u0627 \u064A\u062A\u062D\u0631\u0643 \u0634\u064A\u0621 \u0625\u0644\u0627 \u0628\u0639\u0645\u0644\u0629 \u0648\u0627\u062D\u062F\u0629: \u0645\u062C\u062A\u0645\u0639 \u0643\u0648\u064A\u0646 \u2014 MJT. \u0627\u0633\u062A\u0643\u0634\u0641 \u0627\u0644\u0645\u0643\u0627\u0646 \u0623\u0648\u0644\u0627\u064B.",en:"Here nothing moves without one currency: Mujtama Coin \u2014 MJT. Look around first."}],objective:{ar:"\u0627\u0633\u062A\u0643\u0634\u0641 \u0634\u0642\u062A\u0643 \u0627\u0644\u062C\u062F\u064A\u062F\u0629",en:"Explore your new apartment"},goals:["window","computer","door"],goalLabel:{window:{ar:"\u0627\u0646\u0638\u0631 \u0625\u0644\u0649 \u0627\u0644\u0645\u062F\u064A\u0646\u0629",en:"Look at the city"},computer:{ar:"\u0634\u063A\u0651\u0644 \u0627\u0644\u062D\u0627\u0633\u0648\u0628",en:"Turn on the computer"},door:{ar:"\u062C\u0631\u0651\u0628 \u0627\u0644\u0628\u0627\u0628",en:"Try the door"}},things:{window:{label:{ar:"\u0627\u0644\u0646\u0627\u0641\u0630\u0629",en:"Window"},verb:{ar:"\u0627\u0646\u0638\u0631",en:"Look"},lines:[{ar:"\u0627\u0644\u0645\u062F\u064A\u0646\u0629 \u0627\u0644\u0631\u0642\u0645\u064A\u0629\u2026 \u0643\u0644 \u0646\u0627\u0641\u0630\u0629 \u0645\u0636\u064A\u0626\u0629 \u0641\u064A\u0647\u0627 \u0634\u062E\u0635 \u064A\u0628\u0646\u064A \u062B\u0631\u0648\u062A\u0647.",en:"The Digital City\u2026 behind every lit window, someone is building a fortune."},{ar:"\u0648\u0630\u0627\u0643 \u0627\u0644\u0628\u0631\u062C \u0627\u0644\u0630\u0647\u0628\u064A \u0641\u064A \u0627\u0644\u0642\u0644\u0628: \u0628\u0631\u062C MJT. \u0645\u0646\u0647 \u064A\u0648\u0644\u062F \u0643\u0644 \u0645\u062C\u062A\u0645\u0639 \u0643\u0648\u064A\u0646\u2026",en:"And that golden tower at its heart: the MJT Tower. Every Mujtama Coin is born there\u2026"},{ar:"\u2026\u0648\u0645\u0646\u0647 \u062C\u0627\u0621\u062A \u0627\u0644\u0625\u0634\u0627\u0631\u0629 \u0627\u0644\u062A\u064A \u0631\u0623\u064A\u062A\u0647\u0627 \u0641\u064A \u0627\u0644\u0642\u0637\u0627\u0631.",en:"\u2026and that is where the signal on the train came from."}]},computer:{label:{ar:"\u0627\u0644\u062D\u0627\u0633\u0648\u0628",en:"Computer"},verb:{ar:"\u0634\u063A\u0651\u0644",en:"Turn on"},first:[{ar:"\u0627\u0644\u0634\u0627\u0634\u0629 \u062A\u0631\u0645\u0634 \u0644\u062D\u0638\u0629\u2026 \u0646\u0641\u0633 \u0627\u0644\u0625\u0634\u0627\u0631\u0629: \xAB40\xBB. \u062B\u0645 \u062A\u062E\u062A\u0641\u064A \u0643\u0623\u0646\u0647\u0627 \u0644\u0645 \u062A\u0643\u0646.",en:"The screen flickers for a moment\u2026 the same signal: \u201C40\u201D. Then it is gone, as if it never was."},{ar:"\u062D\u0627\u0633\u0648\u0628 \u0642\u062F\u064A\u0645\u2026 \u0644\u0643\u0646 \u0639\u0644\u064A\u0647 \u0628\u0631\u0646\u0627\u0645\u062C \u062A\u0639\u062F\u064A\u0646 \u0645\u062C\u062A\u0645\u0639 \u0643\u0648\u064A\u0646.",en:"An old computer\u2026 but it runs the Mujtama Coin miner."},{ar:"\u062F\u0648\u0631\u0629 \u0648\u0627\u062D\u062F\u0629 \u0643\u0644 24 \u0633\u0627\u0639\u0629 \u062A\u0639\u0637\u064A\u0643 5 MJT. \u0627\u0628\u062F\u0623\u0647\u0627 \u0648\u062F\u0639\u0647\u0627 \u062A\u0639\u0645\u0644.",en:"One cycle every 24 hours gives you 5 MJT. Start it and let it run."}]},door:{label:{ar:"\u0627\u0644\u0628\u0627\u0628",en:"Door"},verb:{ar:"\u0627\u0641\u062A\u062D",en:"Open"},lines:[{ar:"\u0627\u0644\u0628\u0627\u0628 \u0645\u0642\u0641\u0644. \u0627\u0644\u0634\u0627\u0634\u0629 \u0627\u0644\u0635\u063A\u064A\u0631\u0629 \u0628\u062C\u0627\u0646\u0628\u0647 \u062A\u0642\u0648\u0644: \xAB\u0628\u0627\u0646\u062A\u0638\u0627\u0631 \u0627\u0644\u062A\u0635\u0631\u064A\u062D\xBB.",en:"The door is locked. The little screen beside it says: \u201CAwaiting clearance.\u201D"},{ar:"\u064A\u0628\u062F\u0648 \u0623\u0646 \u0627\u0644\u0645\u062F\u064A\u0646\u0629 \u0644\u0645 \u062A\u0641\u062A\u062D \u0623\u0628\u0648\u0627\u0628\u0647\u0627 \u0644\u0643 \u0628\u0639\u062F\u2026 \u0623\u0643\u0645\u0644 \u0627\u0633\u062A\u0643\u0634\u0627\u0641 \u0634\u0642\u062A\u0643.",en:"It seems the city has not opened its doors to you yet\u2026 finish exploring your apartment."}],open:{ar:"\u0627\u0644\u0628\u0627\u0628 \u0645\u0641\u062A\u0648\u062D. \u0627\u0644\u0634\u0627\u0631\u0639 \u064A\u0646\u062A\u0638\u0631\u0643",en:"The door is open. The street awaits"}},boxes:{label:{ar:"\u0627\u0644\u0635\u0646\u0627\u062F\u064A\u0642",en:"Boxes"},verb:{ar:"\u0627\u0641\u062D\u0635",en:"Inspect"},lines:[{ar:"\u0635\u0646\u0627\u062F\u064A\u0642 \u0627\u0644\u0627\u0646\u062A\u0642\u0627\u0644. \u0645\u0627 \u0632\u0627\u0644\u062A \u0645\u063A\u0644\u0642\u0629\u2026 \u0648\u0635\u0644\u062A\u064E \u0644\u0644\u062A\u0648.",en:"Moving boxes, still sealed\u2026 you only just arrived."}]},bed:{label:{ar:"\u0627\u0644\u0633\u0631\u064A\u0631",en:"Bed"},verb:{ar:"\u0627\u0633\u062A\u0644\u0642\u0650",en:"Lie down"},lines:[{ar:"\u0644\u064A\u0633 \u0648\u0642\u062A \u0627\u0644\u0646\u0648\u0645. \u0627\u0644\u0645\u062F\u064A\u0646\u0629 \u0644\u0627 \u062A\u0646\u0627\u0645.",en:"No time for sleep. The city never sleeps."}]},panel:{label:{ar:"\u0644\u0648\u062D\u0629 \u0627\u0644\u0645\u062F\u064A\u0646\u0629",en:"City board"},verb:{ar:"\u0627\u0642\u0631\u0623",en:"Read"},lines:[{ar:"\xAB\u0623\u062E\u0628\u0627\u0631 \u0627\u0644\u0645\u062F\u064A\u0646\u0629: \u0627\u0644\u0646\u0648\u0627\u0629 \u062A\u0635\u062F\u0631 MJT \u062C\u062F\u064A\u062F\u0629 \u0643\u0644 \u064A\u0648\u0645 \u0644\u0644\u0645\u0639\u062F\u0651\u0646\u064A\u0646.\xBB",en:"\u201CCity news: the Core issues new MJT to miners every day.\u201D"},{ar:"\xAB\u0642\u0631\u064A\u0628\u0627\u064B: \u0627\u0641\u062A\u062A\u0627\u062D \u0645\u062C\u0645\u0651\u0639 \u0627\u0644\u062A\u0639\u062F\u064A\u0646 \u0648\u0627\u0644\u0645\u062A\u062C\u0631 \u0641\u064A \u0648\u0633\u0637 \u0627\u0644\u0645\u062F\u064A\u0646\u0629.\xBB",en:"\u201CComing soon: the Mining Complex and the Market open downtown.\u201D"}]}},done:[{ar:"\u0639\u0631\u0641\u062A \u0645\u0643\u0627\u0646\u0643 \u0627\u0644\u0622\u0646\u060C {name}. \u0627\u0644\u062D\u0627\u0633\u0648\u0628 \u064A\u0639\u062F\u0651\u0646\u060C \u0648\u0627\u0644\u0645\u062F\u064A\u0646\u0629 \u062A\u0646\u062A\u0638\u0631.",en:"Now you know your place, {name}. The computer is mining, and the city is waiting."},{ar:"\u0633\u0645\u0639\u062A\u061F \u0636\u0648\u0621 \u0627\u0644\u0628\u0627\u0628 \u0635\u0627\u0631 \u0630\u0647\u0628\u064A\u0627\u064B\u2026 \u0644\u0642\u062F \u0641\u064F\u062A\u062D \u0644\u0643. \u0627\u062E\u0631\u062C \u0625\u0644\u0649 \u0627\u0644\u0634\u0627\u0631\u0639 \u0648\u0627\u062A\u0628\u0639 \u0627\u0644\u0625\u0634\u0627\u0631\u0629 \u0625\u0644\u0649 \u0628\u0631\u062C MJT.",en:"Hear that? The door light turned gold\u2026 it is open for you. Step out and follow the signal to the MJT tower."}]};export{e as a};
